argv:
set -euo pipefail
fixed_root="/vaso/build/torchvision-cu129"
if [ "$(cat "$fixed_root/owner" 2>/dev/null)" != "{work}" ]; then
  echo "fixed torch build root $fixed_root is owned by another action" >&2
  exit 2
fi
set -euo pipefail; source "$1"; set -- "{work}/wheelhouse"/torchvision-*.whl; if [ "$#" -ne 1 ] || [ ! -f "$1" ]; then echo 'expected exactly one wheel matching torchvision-*.whl' >&2; exit 2; fi; wheel="$1"; python3 -m pip install --no-deps --ignore-installed --no-build-isolation --no-compile --no-warn-script-location --no-index --no-cache-dir --prefix "{out}" "$wheel"; python3 -c 'import pathlib, shutil, sys
prefix = pathlib.Path(sys.argv[1])
for pyc in prefix.rglob("*.pyc"):
    if not pyc.is_symlink():
        pyc.unlink()
for pycache in sorted(prefix.rglob("__pycache__"), reverse=True):
    if pycache.is_dir() and not pycache.is_symlink():
        shutil.rmtree(pycache)
for direct_url in prefix.rglob("direct_url.json"):
    if direct_url.parent.name.endswith(".dist-info") and direct_url.is_file() and not direct_url.is_symlink():
        direct_url.unlink()
        record = direct_url.parent / "RECORD"
        if record.is_file():
            record.write_text("".join(line for line in record.read_text(encoding="utf-8").splitlines(True) if not line.split(",", 1)[0].endswith("/direct_url.json")), encoding="utf-8")
bin_dir = prefix / "bin"
if bin_dir.is_dir():
    for script in sorted(bin_dir.iterdir()):
        if script.is_symlink() or not script.is_file():
            continue
        data = script.read_bytes()
        first, sep, rest = data.partition(b"\n")
        if not sep or not first.startswith(b"#!"):
            continue
        interp = first[2:].strip().split(maxsplit=1)[0]
        name = pathlib.PurePosixPath(interp.decode("utf-8", "ignore")).name
        if name.startswith("python"):
            script.write_bytes(b"#!/usr/bin/env python3\n" + rest)
' "{out}"; mkdir -p "$(dirname "{wheel}")"; cp "$wheel" "{wheel}"
rm -rf "/vaso/build/torchvision-cu129"
